#define _XOPEN_SOURCE 700

#include <stdlib.h>
#include <string.h>

#include "format.h"
#include "msg.h"
#include "path.h"
#include "report.h"
#include "util.h"

/* A path for people: a session file by its place in projects/, others with "~". */
char *report_path(const struct move_ctx *ctx, const char *path)
{
	size_t n;

	if (path == NULL)
		return xstrdup("");
	n = strlen(ctx->projects_dir);
	if (strncmp(path, ctx->projects_dir, n) == 0 && path[n] == '/')
		return xstrdup(path + n + 1);
	return path_tilde(path, ctx->home);
}

/* Takes ownership of text. */
void report_add(struct report *r, enum note_level level, int indent,
    char *text)
{
	struct report_line *l;

	if (r->count == r->cap) {
		r->cap = r->cap ? r->cap * 2 : 16;
		r->lines = xrealloc(r->lines, r->cap * sizeof *r->lines);
	}
	l = &r->lines[r->count++];
	l->level = level;
	l->indent = indent;
	l->text = text;
}

/* A note that opens a group; the notes under it are indented. */
static int is_heading(const char *key)
{
	static const char *const keys[] = {
		"move.repo", "fix.repo", "restore.dir", "restore.merge",
		"restore.entry", "prune.entry", "prune.unavailable", NULL
	};
	size_t i;

	for (i = 0; keys[i] != NULL; i++)
		if (strcmp(keys[i], key) == 0)
			return 1;
	return 0;
}

/* With quiet only errors count: the plan before a question showed the rest. */
void report_notes(struct report *r, const struct move_ctx *ctx, int quiet)
{
	const struct note *n;
	char *a, *b;
	size_t i;

	for (i = 0; i < ctx->note_count; i++) {
		n = &ctx->notes[i];
		if (quiet && n->level != NOTE_ERROR)
			continue;
		a = report_path(ctx, n->a);
		b = n->err != 0 ? xstrdup(strerror(n->err)) :
		    report_path(ctx, n->b);
		report_add(r, n->level, n->level == NOTE_INFO &&
		    !is_heading(n->key), msg_text(n->key, a, b));
		free(a);
		free(b);
	}
}

struct field_count {
	const char *field;
	size_t count;
};

static void plan_config(struct report *r, const struct move_ctx *ctx,
    const char *file, const struct change *c)
{
	char *old, *new;

	old = path_tilde(c->old_value, ctx->home);
	switch (c->kind) {
	case CHANGE_REMOVE:
		report_add(r, NOTE_INFO, 2, msg_text("plan.remove", file,
		    c->field, old));
		break;
	case CHANGE_DROP:
		report_add(r, NOTE_INFO, 2, msg_text("plan.drop", file,
		    c->field, old));
		break;
	default:
		new = path_tilde(c->new_value, ctx->home);
		report_add(r, NOTE_INFO, 2, msg_text("plan.rewrite", file,
		    c->field, old, new));
		free(new);
		break;
	}
	free(old);
}

/*
 * The plan of -n. .claude.json changes one by one; a session file has a
 * change on nearly every line, so it gets a count per field.
 */
void report_plan(struct report *r, const struct move_ctx *ctx)
{
	const struct change_list *plan = &ctx->plan;
	struct field_count *fields;
	char *file, *num;
	size_t i, j, k, f, nfields;

	for (i = 0; i < plan->count; i = j) {
		for (j = i; j < plan->count &&
		    strcmp(plan->items[j].file, plan->items[i].file) == 0; j++)
			;
		file = report_path(ctx, plan->items[i].file);
		if (strcmp(plan->items[i].file, ctx->config_file) == 0) {
			for (k = i; k < j; k++)
				plan_config(r, ctx, file, &plan->items[k]);
			free(file);
			continue;
		}
		fields = xmalloc((j - i) * sizeof *fields);
		nfields = 0;
		for (k = i; k < j; k++) {
			for (f = 0; f < nfields &&
			    strcmp(fields[f].field, plan->items[k].field) != 0; f++)
				;
			if (f == nfields) {
				fields[f].field = plan->items[k].field;
				fields[f].count = 0;
				nfields++;
			}
			fields[f].count++;
		}
		for (f = 0; f < nfields; f++) {
			num = format_count(fields[f].count);
			report_add(r, NOTE_INFO, 2, msg_text("plan.count", file,
			    fields[f].field, num));
			free(num);
		}
		free(fields);
		free(file);
	}
}

size_t report_count(const struct report *r, enum note_level level)
{
	size_t i, n = 0;

	for (i = 0; i < r->count; i++)
		if (r->lines[i].level == level)
			n++;
	return n;
}

void report_free(struct report *r)
{
	size_t i;

	for (i = 0; i < r->count; i++)
		free(r->lines[i].text);
	free(r->lines);
	r->lines = NULL;
	r->count = r->cap = 0;
}
